// D2M Morning Brief — JSON format with clickable links (SO 27 MAR 2026)
const world = $('World Intel').item.json;
const ship = $('Ship Intel').item.json;
const ts = new Date().toLocaleString('en-US', {timeZone: 'America/Denver',
  month: 'short', day: 'numeric', year: 'numeric', hour: 'numeric', minute: '2-digit', hour12: true});

const wData = world.data || world;
const sData = ship.data || ship;

// Smart section formatter — renders articles with inline hyperlinks
function fmtSection(data, label, limit) {
  const items = data.articles || data.items || data.top_alerts || data.alerts || data.results || [];
  if (!items.length) {
    const raw = data.summary || data.result || data.message || '';
    return `*${label}*\n${raw.slice(0, 600)}`;
  }
  const stats = data.news_articles
    ? `_${data.news_articles} articles \u00b7 ${data.urgent_news||0} urgent${data.travel_advisories_total ? ' \u00b7 ' + data.travel_advisories_total + ' advisories' : ''}_\n`
    : '';
  const lines = items.slice(0, limit).map(item => {
    if (typeof item === 'string') return `\u2022 ${item.slice(0,200)}`;
    const title = (item.headline || item.title || item.alert || item.name || '').slice(0, 120);
    const url   = item.url || item.link || '';
    const blurb = (item.summary || item.body || item.relevance || '').slice(0, 160);
    const bullet = url ? `\u2022 [${title}](${url})` : `\u2022 ${title}`;
    return blurb ? `${bullet}\n  _${blurb}_` : bullet;
  });
  return `*${label}*\n${stats}${lines.join('\n')}`;
}

const wSection = fmtSection(wData, '\ud83c\udf0d WORLD INTEL', 5);
const sSection = fmtSection(sData, '\ud83d\udea2 SHIP INTEL', 4);

const msg = `*\ud83d\udcca D2M MORNING BRIEF \u2014 ${ts}*\n_Dreams2Memories Travel \u00b7 Thunderbird OS_\n\n${wSection}\n\n${sSection}`;

// Telegram cap at 4096 chars
const trimmed = msg.length > 4000 ? msg.slice(0, 3997) + '\u2026' : msg;

return [{ json: { message: trimmed, full_world: JSON.stringify(wData), full_ship: JSON.stringify(sData) } }];
